import React, { Component } from 'react';
import NavBar from "../components/NavBar";
import axios from 'axios';
import "./admin.css";

// ✅ Render table row directly (no <div>)
const Todo = (props) => (
  <tr>
    <td>{props.todo.first_name}</td>
    <td>{props.todo.last_name}</td>
    <td>{props.todo.email}</td>
    <td>{props.todo.role}</td>
    <td>
      <a
        href={"/allusers/edit/" + props.todo._id}
        className="btn btn-primary btn-info"
        role="button"
        aria-pressed="true"
      >
        Edit
      </a>
    </td>
  </tr>
);

export default class UserList extends Component {
  constructor(props) {
    super(props);
    this.state = {
      todos: [],
      search: '',
    };

    // Bind search handler
    this.updateSearch = this.updateSearch.bind(this);
  }

  updateSearch(event) {
    this.setState({ search: event.target.value.substr(0, 20) });
  }

  componentDidMount() {
    axios.get('http://localhost:5001/api/users/')
      .then(response => {
        this.setState({ todos: response.data });
      })
      .catch(function (error) {
        console.log(error);
      });
  }

  render() {
    const filteredusers = this.state.todos.filter((user) => {
      return (
        user.first_name.toLowerCase().includes(this.state.search.toLowerCase()) ||
        user.last_name.toLowerCase().includes(this.state.search.toLowerCase()) ||
        user.email.toLowerCase().includes(this.state.search.toLowerCase())
      );
    });

    return (
      <div>
        <NavBar />

        <div
          style={{
            padding: "20px",
            display: "flex",
            flexDirection: "row",
            justifyContent: "space-between"
          }}
        >
          <a
            href="/users/create"
            className="btn btn-primary btn-info btn active"
            role="button"
            aria-pressed="true"
          >
            Create User
          </a>

          <h1 style={{ marginLeft: "-200px", textDecoration: "underline", color: "#F0542D" }}>
            Manage Users
          </h1>

          <input
            type="text"
            placeholder="Search..."
            className="form-control input-sm"
            style={{ width: "250px" }}
            value={this.state.search}
            onChange={this.updateSearch}
          />
        </div>

        <div className="container" style={{ border: "10px solid lightgray" }}>
          <table
            className="table table-striped"
            id="usertable"
            ref={(el) => this.el = el}
            data-order='[[ 1, "asc" ]]'
            data-page-length='25'
          >
            <thead>
              <tr>
                <th>First Name</th>
                <th>Last Name</th>
                <th>Email</th>
                <th>Role</th>
                <th>Action</th>
              </tr>
            </thead>

            <tbody>
              {filteredusers.map((currentTodo, i) => (
                <Todo todo={currentTodo} key={i} />
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  }
}
